parent.location.href ='/00O34000005etju?pv0={!SUBSTITUTE(BoB_Coverage__c.Sales_Rep_Name__c, "'", "\'")}&pv1={!SUBSTITUTE(TEXT(BoB_Coverage__c.Sales_Rep_Role__c), "'", "\'")}'; 
}else{ 
parent.location.href ='/00O340000064qcX?pv0={!SUBSTITUTE(BoB_Coverage__c.Sales_Rep_Name__c, "'", "\'")}&pv1={!SUBSTITUTE(TEXT(BoB_Coverage__c.Sales_Rep_Role__c), "'", "\'")}';
}
